-- ============================================================
-- v57: Google My Maps-এর সব ২৫৯টি মণ্ডপ সাইটের ডাটাবেসে হুবহু একই নামে মিলিয়ে দেওয়া + অঞ্চল/থানা ভাগ
-- Supabase → SQL Editor → New query → পুরোটা বসিয়ে Run
--
-- ডেটার উৎস: chattogram-puja-sob-map.kmz (মহানগর ১৭৯, উত্তর চট্টগ্রাম ৩৩, দক্ষিণ চট্টগ্রাম ৪৭)।
-- নাম ও স্থানাঙ্ক ফাইল থেকে হুবহু নেওয়া; কোনো নাম বা স্থানাঙ্ক অনুমান করা হয়নি।
--
-- এই ফাইল যা করে (২০২৬ সালের মণ্ডপে):
--   ১) সাইটে আগে থেকে থাকা মণ্ডপকে ম্যাপের সঙ্গে মেলায়: আগে হুবহু নামে, তারপর বানানের
--      ইউনিকোড-ভেদ মিটিয়ে, তারপর ম্যাপের "পুরনো ম্যাপে নাম" দিয়ে। মিলে গেলে নাম, এলাকা, স্থানাঙ্ক ম্যাপের মতো করে দেয়।
--   ২) যেগুলো সাইটে ছিলই না সেগুলো নতুন মণ্ডপ হিসেবে "প্রকাশিত" করে ঢোকায়।
--   ৩) এলাকা লেখা হয় "অঞ্চল · থানা · এলাকা" আকারে (যেমন "মহানগর · কোতোয়ালী · পাথরঘাটা")।
--      এই লেখা থেকেই সাইটের তালিকা অঞ্চল ও থানা অনুযায়ী ভাগ হয়।
--   ৪) ঠিকানা: ম্যাপের ঠিকানা থাকলে সেটা, না থাকলে সাইটের আগের ঠিকানাই থাকে।
--      বিবরণ: সাইটের আগের বিবরণ থাকলে সেটাই থাকে; ফাঁকা হলে ম্যাপের "এখানে যেসব পূজা হয়" বসে।
--      ম্যাপে "অবস্থান আনুমানিক" লেখা (৪৮টিতে) থাকলে বিবরণে সেই কথাটুকু যোগ হয়।
--   ৫) কিছু মোছে না। ম্যাপে নেই অথচ সাইটে আছে এমনগুলো শেষের তালিকায় দেখায়।
-- বারবার চালালেও ডুপ্লিকেট হয় না।
-- ============================================================

drop table if exists pg_temp.kmz;
create temp table kmz (
  seq        int primary key,
  name       text not null,
  area       text not null,
  address    text,
  pujas_line text,
  approx     boolean not null default false,
  old_name   text,
  lat        numeric not null,
  lng        numeric not null,
  matched_id uuid
);

drop table if exists pg_temp.kmz_log;
create temp table kmz_log (seq int, old_name text, new_name text, how text);


do $$
declare
  v_year uuid;
  t      int;
  r      record;
  v_id   uuid;
begin
  select id into v_year from public.puja_years where year = 2026;
  if v_year is null then
    raise exception '২০২৬ সালের পূজাবর্ষ পাওয়া যায়নি (sql/03_first_year.sql আগে চালান)';
  end if;

  -- মেলানো: ধাপ ১ হুবহু নাম, ধাপ ২ ইউনিকোড মিলিয়ে নাম, ধাপ ৩ ম্যাপের "পুরনো ম্যাপে নাম"
  -- একটি সাইটের মণ্ডপ একটি ম্যাপ-পিনের সঙ্গেই মেলে (দুবার নয়)।
  for t in 1..3 loop
    for r in select * from kmz where matched_id is null order by seq loop
      select m.id into v_id
        from public.mandapas m
       where m.year_id = v_year
         and not exists (select 1 from kmz c where c.matched_id = m.id)
         and (   (t = 1 and m.name = r.name)
              or (t = 2 and normalize(btrim(m.name), nfc) = normalize(btrim(r.name), nfc))
              or (t = 3 and r.old_name is not null
                        and normalize(btrim(m.name), nfc) = normalize(btrim(r.old_name), nfc)))
       order by (m.status = 'published') desc, m.id
       limit 1;
      if v_id is not null then
        update kmz set matched_id = v_id where seq = r.seq;
          select r.seq, m.name, r.name, case t when 1 then 'হুবহু' when 2 then 'ইউনিকোড' else 'পুরনো নাম' end
            from public.mandapas m where m.id = v_id;
      end if;
    end loop;
  end loop;

  -- মিলে যাওয়াগুলো হালনাগাদ
  update public.mandapas m
     set name        = k.name,
         area        = k.area,
         address     = coalesce(k.address, m.address),
         description = nullif(concat_ws(E'\n',
                         coalesce(nullif(btrim(m.description), ''), k.pujas_line),
                         case when k.approx
                                and coalesce(nullif(btrim(m.description), ''), k.pujas_line, '') not like '%অবস্থান আনুমানিক%'
                              then 'অবস্থান আনুমানিক' end), ''),
         latitude    = k.lat,
         longitude   = k.lng,
         status      = 'published'
    from kmz k
   where k.matched_id = m.id;

  -- সাইটে না-থাকাগুলো নতুন মণ্ডপ হিসেবে যোগ
  select v_year, k.name, k.area, k.address,
         nullif(concat_ws(E'\n', k.pujas_line, case when k.approx then 'অবস্থান আনুমানিক' end), ''),
         k.lat, k.lng, 'published'
    from kmz k
   where k.matched_id is null
   order by k.seq;
end $$;

-- ------------------------------------------------------------
-- ঐচ্ছিক ক: ম্যাপে নেই এমন প্রকাশিত মণ্ডপ আর্কাইভ করতে চাইলে নিচের ৪ লাইনের `-- ` তুলে দিন
-- (কিছু মোছা হয় না; শুধু সাইটের তালিকা থেকে সরে যায়। শেষের ক্রম ৭-এর তালিকা আগে দেখে নিন)।
-- update public.mandapas m set status = 'archived'
--  where m.year_id = (select id from public.puja_years where year = 2026)
--    and m.status = 'published'
--    and not exists (select 1 from kmz k where k.matched_id = m.id);
--
-- ঐচ্ছিক খ: ম্যাপে "অবস্থান আনুমানিক" লেখা পিনগুলোর স্থানাঙ্ক সাইট থেকে সরিয়ে
-- "লোকেশন পাওয়া যায়নি" দেখাতে চাইলে (আলাদা করে, এই ফাইল চালানোর পরে):
-- update public.mandapas set latitude = null, longitude = null
--  where year_id = (select id from public.puja_years where year = 2026)
--    and description like '%অবস্থান আনুমানিক%';
-- ------------------------------------------------------------

-- যাচাই (সব ফল একটাই তালিকায়)
--   ১. ম্যাপের মণ্ডপ              → ২৫৯
--   ২. সাইটে হুবহু নামে আছে        → ২৫৯ (পুরো ম্যাপ)
--   ৩. সাইটে নেই                  → ০ (একটাও আসা উচিত নয়)
--   ৪. অঞ্চল ভাগ                  → মহানগর ১৭৯, উত্তর ৩৩, দক্ষিণ ৪৭ (ম্যাপের ও সাইটের সংখ্যা মিলতে হবে)
--   ৫. সাইটে স্থানাঙ্কসহ           → ম্যাপের পিনগুলোর সবই
--   ৬. একই নামে একাধিক            → ০
--   ৭. সাইটে আছে, ম্যাপে নেই      → থাকলে নাম দেখাবে (মুছে যায়নি)
--   ৮. নাম হুবহু করা হয়েছে        → পুরনো → নতুন
with pub as (
  select m.* from public.mandapas m join public.puja_years y on y.id = m.year_id
  where y.year = 2026 and m.status = 'published'
)
select 1 as ক্রম, '১. ম্যাপের মণ্ডপ' as বিষয়, count(*)::text as মান from kmz
union all
select 2, '২. সাইটে হুবহু নামে আছে', count(*)::text from kmz k where exists (select 1 from pub p where p.name = k.name)
union all
select 3, '৩. সাইটে নেই: ' || k.name, '১' from kmz k where not exists (select 1 from pub p where p.name = k.name)
union all
select 4, '৪. ম্যাপে ' || split_part(area, ' · ', 1), count(*)::text from kmz group by split_part(area, ' · ', 1)
union all
select 4, '৪. সাইটে ' || split_part(p.area, ' · ', 1), count(*)::text from pub p
  where exists (select 1 from kmz k where k.matched_id = p.id) group by split_part(p.area, ' · ', 1)
union all
select 5, '৫. সাইটে স্থানাঙ্কসহ (ম্যাপের পিনগুলোর মধ্যে)', count(*)::text from pub p
  where p.latitude is not null and p.longitude is not null and exists (select 1 from kmz k where k.name = p.name)
union all
select 6, '৬. একই নামে একাধিক: ' || name, count(*)::text from pub group by name having count(*) > 1
union all
select 7, '৭. সাইটে আছে, ম্যাপে নেই: ' || p.name, p.id::text from pub p
  where not exists (select 1 from kmz k where k.name = p.name)
union all
select 8, '৮. [' || l.how || '] ' || l.old_name, '→ ' || l.new_name from kmz_log l where l.old_name <> l.new_name
order by 1, 2, 3;
